import {createHmac,timingSafeEqual} from 'node:crypto';import {assertUuid} from './context.mjs';
const canonical=x=>JSON.stringify(x,Object.keys(x).sort());
export function signEnvelope(input,key){if(!(key instanceof Buffer)||key.length<32)throw new Error('Signing key must be at least 256 bits');const body=Object.freeze({version:1,tenantId:assertUuid(input.tenantId,'tenantId'),messageId:assertUuid(input.messageId,'messageId'),issuedAt:input.issuedAt,expiresAt:input.expiresAt,type:input.type,payloadHash:input.payloadHash});if(!Number.isFinite(Date.parse(body.issuedAt))||!Number.isFinite(Date.parse(body.expiresAt))||Date.parse(body.expiresAt)<=Date.parse(body.issuedAt))throw new Error('Invalid envelope lifetime');const signature=createHmac('sha256',key).update(canonical(body)).digest('hex');return {body,signature};}
export function verifyEnvelope(envelope,key,expectedTenantId,now=Date.now()){const expected=createHmac('sha256',key).update(canonical(envelope.body)).digest();const supplied=Buffer.from(envelope.signature??'','hex');if(expected.length!==supplied.length||!timingSafeEqual(expected,supplied))throw new Error('Envelope signature rejected');if(envelope.body.tenantId!==assertUuid(expectedTenantId,'expectedTenantId'))throw new Error('Envelope tenant mismatch');if(Date.parse(envelope.body.expiresAt)<=now)throw new Error('Envelope expired');return envelope.body;}
